<?php $title="AI Leads";require "includes/header.php";$r=$conn->query("SELECT * FROM leads ORDER BY score DESC");?><div class="section-title"><div><h2>🎯 AI Lead Pipeline</h2><p class="muted">Lead priority using AI-style scoring.</p></div><a class="btn primary" href="add_lead.php">+ Add Lead</a></div><div class="card"><table><tr><th>Lead</th><th>Interest</th><th>Source</th><th>AI Score</th><th>Status</th></tr><?php while($x=$r->fetch_assoc()):?><tr><td><?=e($x["name"])?><br><?=e($x["phone"])?></td><td><?=e($x["interest"])?></td><td><?=e($x["source"])?></td><td><span class="score"><?=$x["score"]?></span>/100</td><td><span class="badge"><?=e($x["status"])?></span></td></tr><?php endwhile;?></table></div><?php require "includes/footer.php";?>